      synopsis:
        'City of Silver (Episode 1): Above the undying gray fog, Klein Moretti, the enigmatic The Fool, presided over the Tarot Club when a new, distant prayer echoed through the mists. Reaching across the veil, he summoned Derrick Berg from the City of Silver—a cursed bastion trapped within the Forsaken Land of God. Through Derrick’s haunting tales, the grim history of this sunless city was unveiled. Seeking salvation for his people, Derrick pledged his soul to The Fool’s grace. From the twenty-two Major Arcana, he chose his mantle: "The Sun."\n\nThe Marked Hunt (Episodes 2 and 3): The gathering then turned to matters of blood and ambition. "The Hanged Man," Alger Wilson, proposed a high-stakes exchange. He sought the head of Qilangos, one of the infamous seven Pirate Admirals, and tasked "Justice," Audrey Hall, with leveraging her noble influence in Backlund to hunt the wind-blessed killer.\n\nIn the foggy streets of the Loen capital, Audrey’s quest led her to the Beyonder duo, Fors Wall and Xio Derecha. As the web tightened around the Admiral, Klein sought the intervention of his mentor, the mysterious Mr. Azik. By weaving together the threads of divinity, ancient power, and mortal cunning, The Fool ensured the Tarot Club’s first great triumph: the fall of Qilangos.\n\n(Source: Crunchyroll)',
