      synopsis:
        'Three years ago, Nalan Yanran, the young sect leader of the Yunlan Sect, rashly broke off her engagement. Feeling deeply humiliated, Xiao Yan made a three-year pact with Nalan Yanran. For this pact, Xiao Yan cultivated tirelessly, enduring trials from the Magical Beast Mountain Range to the Tagor Desert, from alchemy to the excruciating pain of absorbing a strange fire—all to prove the saying: "Thirty years east of the river, thirty years west of the river; never underestimate a young man\'s potential." Now, the men of the Xiao family will rise to the challenge, never retreating. Xiao Yan\'s path of growth continues…\n\n(Source: Tencent, translated)',
